let visit=null;
function current(book,owner){if(!visit||visit.book!==book||visit.owner!==owner)visit={book,owner,id:'twelve',step:0};return visit;}
export function journeySelection(book,owner){const v=current(book,owner);return {id:v.id,step:v.step};}
export function chooseJourney(book,owner,id){if(!learningJourneys.some(j=>j.id===id))return false;const v=current(book,owner);if(v.id!==id){v.id=id;v.step=0;}return true;}
export function chooseJourneyStop(book,owner,step){if(!Number.isInteger(step)||step<0||step>3)return false;current(book,owner).step=step;return true;}
export function journeyFacts(book,owner){const v=current(book,owner),stop=learningJourneys.find(j=>j.id===v.id).stops[v.step];return [...new Map(stop.facts.flatMap(([a,b])=>[[a,b],[b,a]]).map(p=>[p.join('x'),p])).values()];}
export function prepareJourneyDisplay(book,owner,o={}){
 const facts=journeyFacts(book,owner);if(!facts.length)return {ok:true,changed:false};
 try{if(typeof o.exposeFacts!=='function'||typeof o.canExport!=='function')return {ok:false,changed:false};const candidate=structuredClone(book);o.exposeFacts(facts,candidate);if(!o.canExport(candidate))return {ok:false,changed:false};const before=JSON.stringify(book);o.exposeFacts(facts,book);return {ok:true,changed:JSON.stringify(book)!==before};}catch{return {ok:false,changed:false};}
}
export function learningJourneysPage(book,owner,{ready=true}={}){
 const v=current(book,owner),j=learningJourneys.find(j=>j.id===v.id),s=j.stops[v.step];
 return `<div class="learning-journeys" data-journeys><header><a class="back" href="#home">← Back to town</a><h1>Follow an idea through town</h1><p>Try a stop, change direction, or come back another day. Every place is open.</p></header><nav class="journey-choices" aria-label="Choose an idea">${learningJourneys.map(x=>`<button data-journey="${x.id}" aria-pressed="${x.id===v.id}">${esc(x.title)}</button>`).join('')}</nav><p class="journey-purpose">${esc(j.purpose)}</p><nav class="journey-stops" aria-label="Choose a stop">${j.stops.map((x,i)=>`<button data-journey-stop="${i}" aria-label="Stop ${i+1}: ${esc(x.title)}" aria-pressed="${i===v.step}"><span>${i+1}</span>${esc(x.title)}</button>`).join('')}</nav><section class="journey-sheet"><h2 tabindex="-1" data-journey-heading>${esc(s.title)}</h2>${ready?`<div class="journey-spread"><div class="journey-picture">${s.art}</div><div><p>${esc(s.text)}</p>${hearButton(s.text+' '+s.ask,'Hear this idea')}<p class="journey-question">${esc(s.ask)}</p><a class="primary" href="${s.route}">${esc(s.action)}</a><p class="journey-choose">${esc(s.choose)}</p>${s.extra?`<a href="${s.extra}">${esc(s.extraLabel)}</a>`:''}</div></div>`:'<p>We could not safely keep track of this shown example in this notebook. Your work is unchanged. Choose another stop, or download your work from <a href="#notes">Grown-up notes</a>. All other places remain open.</p>'}<div class="journey-pages"><button data-journey-move="-1" ${v.step===0?'disabled':''}>← Previous stop</button><span>Stop ${v.step+1} of 4</span><button data-journey-move="1" ${v.step===3?'disabled':''}>Next stop →</button></div></section><details class="journey-grownup"><summary>For grown-ups</summary><p>Four stops can take any number of sittings. Discuss, draw, use help, or skip. Shown examples are recorded as familiarity in the existing notebook; visits do not establish independent learning. These are small journeys, not complete courses.</p></details></div>`;
}
export function bindLearningJourneys(book,{notebook,explorerId,isActive,render}){
 const root=document.querySelector('[data-journeys]');if(!root)return;const owner=explorerId(),route=location.hash;
 const live=()=>root.isConnected&&notebook()===book&&explorerId()===owner&&isActive()&&location.hash===route;
 root.addEventListener('click',event=>{if(!live()||event.target.closest?.('[hidden]')){event.preventDefault();event.stopImmediatePropagation();}},{capture:true});
 root.querySelectorAll('[data-journey],[data-journey-stop],[data-journey-move]').forEach(b=>b.onclick=()=>{
  if(!live()||!b.isConnected||!root.contains(b)||b.disabled||b.closest('[hidden]'))return;
  if(b.hasAttribute('data-journey'))chooseJourney(book,owner,b.dataset.journey);
  else chooseJourneyStop(book,owner,b.hasAttribute('data-journey-stop')?Number(b.dataset.journeyStop):current(book,owner).step+Number(b.dataset.journeyMove));
  render();document.querySelector('[data-journey-heading]')?.focus();
 });
}
